type Money={amount:string;currencyCode:string};
type ImageData={url:string;altText?:string|null;width?:number|null;height?:number|null};
type Variant={id:string;title:string;availableForSale:boolean;sku?:string|null;price:Money;compareAtPrice?:Money|null;selectedOptions:{name:string;value:string}[];image?:ImageData|null};
type Product={id:string;handle:string;name:string;brand:string;description:string;descriptionHtml?:string;productType?:string;price:Money;compareAtPrice?:Money|null;availableForSale:boolean;images:ImageData[];variants:Variant[];href:string;rating?:number;reviewCount?:number;boughtCount?:number;seo?:{title?:string|null;description?:string|null}};
type FacetValue={id:string;label:string;count?:number|null;input:any};
type Facet={id:string;label:string;presentation?:string|null;type?:string|null;values:FacetValue[]};
type AppliedFacet={filterId:string;label:string;input:any;token:string};
type Collection={id:string;handle:string;title:string;description?:string|null;image?:ImageData|null;products:Product[];pageInfo?:{hasNextPage:boolean;endCursor:string|null};filters?:Facet[]};
type CartLine={id:string;quantity:number;merchandise:{id:string;title:string;price:Money;image?:ImageData|null;product:{title:string;handle:string;featuredImage?:ImageData|null}}};
type Cart={id:string;checkoutUrl:string;totalQuantity:number;cost:{subtotalAmount:Money;totalAmount:Money};lines:CartLine[]};
type BlogArticle={id:string;handle:string;title:string;excerpt?:string|null;excerptHtml?:string|null;contentHtml:string;publishedAt:string;image?:ImageData|null;tags:string[];blogHandle:string;blogTitle:string;seo?:{title?:string|null;description?:string|null}};
type Blog={id:string;handle:string;title:string;articles:BlogArticle[]};

