function ContactPage({collections}:{collections:Collection[]}){return <main className="mx-auto max-w-[1100px] px-4 py-10"><div className="grid gap-6 md:grid-cols-2"><div className="border border-slate-200 bg-white p-7 md:p-10"><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">Contact BuyHoreca</div><h1 className="mt-2 text-4xl font-bold">How can we help?</h1><p className="mt-4 text-sm leading-7 text-slate-600">For product questions, commercial requirements, quotations and hospitality supply enquiries, contact the BuyHoreca team.</p><div className="mt-7 grid gap-4 text-sm"><a href="tel:+971509936806" className="flex items-center gap-3 font-bold"><Phone className="text-[#008f68]" size={18}/> +971 50 993 6806</a><a href="tel:+971565334464" className="flex items-center gap-3 font-bold"><Phone className="text-[#008f68]" size={18}/> +971 56 533 4464</a><a href="mailto:info@buyhoreca.com" className="flex items-center gap-3 font-bold"><Mail className="text-[#008f68]" size={18}/> info@buyhoreca.com</a><div className="flex items-start gap-3 font-bold"><MapPin className="mt-0.5 text-[#008f68]" size={18}/>Dubai, U.A.E.</div></div><div className="mt-7 flex gap-3"><Link href="/quote" className="rounded bg-[#008f68] px-5 py-3 text-sm font-semibold text-white">Request a Quote</Link><a href="https://wa.me/971565334464" target="_blank" rel="noreferrer" className="rounded border border-slate-300 px-5 py-3 text-sm font-semibold">WhatsApp</a></div></div><div className="overflow-hidden border border-slate-200 bg-[#0b2b22]"><CompanyImage alt="BuyHoreca hospitality supply" className="h-full min-h-[420px] w-full object-cover"/></div></div></main>}
function FAQPage(){const faqs=[["Where do prices come from?","Product pricing and availability are read from the live Shopify catalogue."],["Can I request a bulk quotation?","Yes. Use the Request a Quote page for bulk, project, unavailable or specification-sensitive requirements."],["Can I buy directly online?","Products that are available for sale can be added to the Shopify cart and sent to Shopify checkout."],["Can I search by product or SKU?","The storefront search is connected to Shopify product search and also exposes category suggestions while typing."],["Where are blog articles managed?","Blog content is managed in Shopify and displayed through the Storefront API when published."]];return <main className="mx-auto max-w-[1000px] px-4 py-10"><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">Support</div><h1 className="mt-2 text-4xl font-bold">Frequently Asked Questions</h1><div className="mt-7 grid gap-3">{faqs.map(([q,a])=><details key={q} className="border border-slate-200 bg-white p-5"><summary className="cursor-pointer font-bold">{q}</summary><p className="mt-3 max-w-3xl text-sm leading-6 text-slate-600">{a}</p></details>)}</div></main>}
function TrackOrderPage(){const [ref,setRef]=useState("");const submit=(e:any)=>{e.preventDefault();const message=`Hello BuyHoreca, please help me track order/reference ${ref.trim()||"(not provided)"}.`;location.href=`https://wa.me/971565334464?text=${encodeURIComponent(message)}`};return <main className="mx-auto max-w-3xl px-4 py-12"><div className="border border-slate-200 bg-white p-7 md:p-10"><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">Order support</div><h1 className="mt-2 text-4xl font-bold">Track an Order</h1><p className="mt-3 text-sm leading-6 text-slate-600">Enter your order reference and send it to the BuyHoreca support team for current status or delivery assistance.</p><form onSubmit={submit}><label className="mt-7 block text-xs font-semibold uppercase tracking-wider text-slate-500" htmlFor="order-ref">Order number / reference</label><input id="order-ref" value={ref} onChange={e=>setRef(e.target.value)} className="mt-2 h-12 w-full border border-slate-300 px-4 outline-none focus:border-[#008f68] focus:ring-2 focus:ring-[#008f68]/10" placeholder="e.g. #100123"/><div className="mt-4 flex flex-wrap gap-3"><button type="submit" className="rounded bg-[#008f68] px-5 py-3 text-sm font-semibold text-white">Send to Support</button><a href="mailto:info@buyhoreca.com" className="rounded border border-slate-300 px-5 py-3 text-sm font-semibold">Email support</a><Link href="/contact" className="rounded border border-slate-300 px-5 py-3 text-sm font-semibold">Contact details</Link></div></form></div></main>}

function BlogArticleLoader({blogHandle,articleHandle}:{blogHandle:string;articleHandle:string}){const [article,setArticle]=useState<BlogArticle|null>(null);const [loading,setLoading]=useState(true);useEffect(()=>{getArticle(blogHandle,articleHandle).then(setArticle).catch(()=>setArticle(null)).finally(()=>setLoading(false))},[blogHandle,articleHandle]);if(loading)return <main className="mx-auto max-w-[1100px] px-4 py-20 text-center"><RefreshCw className="mx-auto animate-spin text-[#008f68]"/></main>;return article?<BlogArticlePage article={article}/>:<SimplePage title="Article not found" text="This Shopify article could not be found or is not published to the Storefront API."/>}

function App(){
 const pathname=usePathname();const params=useSearchParams();const query=params.get("q")||"";
 const [products,setProducts]=useState<Product[]>([]);const [collections,setCollections]=useState<Collection[]>([]);const [product,setProduct]=useState<Product|null>(null);const [productLoading,setProductLoading]=useState(false);const [cart,setCart]=useState<Cart|null>(null);const [cartId,setCartId]=useState<string|null>(null);const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [cartOpen,setCartOpen]=useState(false);const [quick,setQuick]=useState<Product|null>(null);const [wishlist,setWishlist]=useState<string[]>([]);const [compare,setCompare]=useState<string[]>([]);const [toast,setToast]=useState<string>("");const [cartPulse,setCartPulse]=useState(false);const [storageReady,setStorageReady]=useState(false);
 const showToast=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(""),2800)};
 useEffect(()=>{setWishlist(readStoredIds(WISHLIST_KEY));setCompare(readStoredIds(COMPARE_KEY));setStorageReady(true);const id=localStorage.getItem("buyhoreca_shopify_cart_id");if(id){setCartId(id);shopifyFetch<any>(CART,{id}).then(d=>{const next=normCart(d.cart);if(next)setCart(next);else localStorage.removeItem("buyhoreca_shopify_cart_id")}).catch(()=>localStorage.removeItem("buyhoreca_shopify_cart_id"))}},[]);
 useEffect(()=>{if(!storageReady)return;writeStoredJSON(WISHLIST_KEY,wishlist)},[wishlist,storageReady]);
 useEffect(()=>{if(!storageReady)return;writeStoredJSON(COMPARE_KEY,compare)},[compare,storageReady]);
 useEffect(()=>{const onWish=(e:Event)=>{const detail=((e as CustomEvent).detail||[]) as unknown[];setWishlist(readStoredIds(WISHLIST_KEY).length?readStoredIds(WISHLIST_KEY):detail.filter((x):x is string=>typeof x==="string"))};const onComp=(e:Event)=>{const detail=((e as CustomEvent).detail||[]) as unknown[];setCompare(readStoredIds(COMPARE_KEY).length?readStoredIds(COMPARE_KEY):detail.filter((x):x is string=>typeof x==="string").slice(0,4))};const onStorage=(e:StorageEvent)=>{if(e.key===WISHLIST_KEY)setWishlist(readStoredIds(WISHLIST_KEY));if(e.key===COMPARE_KEY)setCompare(readStoredIds(COMPARE_KEY).slice(0,4))};const onToast=(e:Event)=>{const message=(e as CustomEvent).detail;if(typeof message==="string")showToast(message)};window.addEventListener("buyhoreca:wishlist",onWish);window.addEventListener("buyhoreca:compare",onComp);window.addEventListener("storage",onStorage);window.addEventListener("buyhoreca:toast",onToast);return()=>{window.removeEventListener("buyhoreca:wishlist",onWish);window.removeEventListener("buyhoreca:compare",onComp);window.removeEventListener("storage",onStorage);window.removeEventListener("buyhoreca:toast",onToast)}},[]);
 const needsProducts=pathname==="/"||pathname==="/shop"||pathname==="/brands"||pathname==="/wishlist"||pathname==="/compare"||pathname.startsWith("/business/");
 const refresh=async()=>{setLoading(true);setError("");try{const [c,p]=await Promise.all([getCollections(),needsProducts?getProducts(48,null,undefined,"BEST_SELLING",false):Promise.resolve({products:[],pageInfo:{hasNextPage:false,endCursor:null}})]);setCollections(c);setProducts(p.products)}catch{setError("The live catalogue could not be loaded. Check your Shopify environment variables and API route.")}finally{setLoading(false)}};
 useEffect(()=>{void refresh();const t=setInterval(refresh,300000);return()=>clearInterval(t)},[pathname]);
 useEffect(()=>{if(pathname.startsWith("/products/")){setProductLoading(true);getProduct(pathname.split("/")[2]||"").then(p=>{setProduct(p);if(p)trackEvent("view_item",{item_id:p.id,item_name:p.name,item_brand:p.brand,value:p.price.amount,currency:p.price.currencyCode})}).catch(()=>setProduct(null)).finally(()=>setProductLoading(false))}else{setProduct(null);setProductLoading(false)}},[pathname]);
 useEffect(()=>{if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;const l=new Lenis({duration:0.8,smoothWheel:true});let id=0;const raf=(t:number)=>{l.raf(t);id=requestAnimationFrame(raf)};id=requestAnimationFrame(raf);return()=>{cancelAnimationFrame(id);l.destroy()}},[]);
 useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if(e.key==="Escape"){setQuick(null);setCartOpen(false)}};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey)},[]);
 const add=async(p:Product,v?:Variant,q=1)=>{const selected=v||p.variants.find(x=>x.availableForSale)||p.variants[0];if(!selected)return null;let currentId=cartId;try{let d:any;if(!currentId){d=await shopifyFetch(CREATE_CART,{lines:[{merchandiseId:selected.id,quantity:q}]});if(d.cartCreate?.userErrors?.length)throw new Error(d.cartCreate.userErrors[0].message);const next=normCart(d.cartCreate?.cart);if(!next)throw new Error("Unable to create cart");setCart(next);setCartId(next.id);localStorage.setItem("buyhoreca_shopify_cart_id",next.id);setCartOpen(true);setCartPulse(true);showToast(`${p.name} added to cart`);window.setTimeout(()=>setCartPulse(false),520);return next;}d=await shopifyFetch(ADD_LINES,{cartId:currentId,lines:[{merchandiseId:selected.id,quantity:q}]});if(d.cartLinesAdd?.userErrors?.length)throw new Error(d.cartLinesAdd.userErrors[0].message);const next=normCart(d.cartLinesAdd?.cart);if(!next)throw new Error("Unable to update cart");setCart(next);setCartOpen(true);setCartPulse(true);showToast(`${p.name} added to cart`);window.setTimeout(()=>setCartPulse(false),520);return next}catch(err){if(currentId){localStorage.removeItem("buyhoreca_shopify_cart_id");setCartId(null);setCart(null);try{const d:any=await shopifyFetch(CREATE_CART,{lines:[{merchandiseId:selected.id,quantity:q}]});if(d.cartCreate?.userErrors?.length)throw new Error(d.cartCreate.userErrors[0].message);const next=normCart(d.cartCreate?.cart);if(next){setCart(next);setCartId(next.id);localStorage.setItem("buyhoreca_shopify_cart_id",next.id);setCartOpen(true);setCartPulse(true);showToast(`${p.name} added to cart`);window.setTimeout(()=>setCartPulse(false),520);return next}}catch{} }showToast(err instanceof Error?err.message:"We couldn't add this product right now.");return null}};
 const update=async(id:string,q:number)=>{if(!cartId)return;if(q<=0)return remove(id);try{const d:any=await shopifyFetch(UPDATE_LINES,{cartId,lines:[{id,quantity:q}]});if(d.cartLinesUpdate?.userErrors?.length)throw new Error(d.cartLinesUpdate.userErrors[0].message);setCart(normCart(d.cartLinesUpdate.cart))}catch(e){showToast(e instanceof Error?e.message:"Unable to update cart")}};
 const remove=async(id:string)=>{if(!cartId)return;try{const d:any=await shopifyFetch(REMOVE_LINES,{cartId,lineIds:[id]});if(d.cartLinesRemove?.userErrors?.length)throw new Error(d.cartLinesRemove.userErrors[0].message);setCart(normCart(d.cartLinesRemove.cart))}catch(e){showToast(e instanceof Error?e.message:"Unable to remove item")}};
 let content:ReactNode;if(loading)content=<main className="mx-auto max-w-[1600px] px-4 py-20"><div className="grid gap-3 md:grid-cols-6">{Array.from({length:12}).map((_,i)=><div key={i} className="bh-skeleton h-64 rounded border border-slate-200"/> )}</div></main>;else if(error)content=<SimplePage title="Store temporarily unavailable" text={error}><button onClick={refresh} className="bh-primary-button mt-6">Try again <RefreshCw size={15}/></button></SimplePage>;else if(pathname==="/")content=<Home products={products} collections={collections} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/shop"||pathname==="/search")content=pathname==="/search"?<SearchPage q={query} categories={collections} onAdd={add} onQuick={setQuick}/>:<Catalog initial={products} collections={collections} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/categories"||pathname==="/collections")content=<CategoryIndex collections={collections}/>;else if(pathname.startsWith("/categories/")){const c=collections.find(x=>x.handle===pathname.split("/")[2]);content=<CategoryLoader handle={pathname.split("/")[2]||""} fallback={c||null} onAdd={add} onQuick={setQuick}/>;}else if(pathname.startsWith("/products/"))content=productLoading?<SimplePage title="Loading product…"/>:product?<ProductPage product={product} onAdd={add} onQuick={setQuick}/>:<SimplePage title="Product not found" text="This product is no longer available through the live Shopify catalogue."><Link href="/shop" className="bh-primary-button mt-6 inline-flex">Back to products <ArrowRight size={15}/></Link></SimplePage>;else if(pathname==="/brands")content=<BrandIndex products={products}/>;else if(pathname.startsWith("/brands/")){const b=decodeURIComponent(pathname.split("/")[2]||"");content=<BrandPage name={b} onAdd={add} onQuick={setQuick}/>;}else if(pathname==="/business")content=<BusinessIndex/>;else if(pathname.startsWith("/business/"))content=<BusinessPage name={titleFromSlug(pathname.split("/")[2]||"")} products={products} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/cart")content=<CartPage cart={cart} onUpdate={update} onRemove={remove}/>;else if(pathname==="/wishlist")content=<Wishlist ids={wishlist} products={products} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/compare")content=<ComparePage ids={compare} products={products} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/quote")content=<QuotePage/>;else if(pathname==="/about")content=<AboutPage collections={collections}/>;else if(pathname==="/contact")content=<ContactPage collections={collections}/>;else if(pathname==="/faq")content=<FAQPage/>;else if(pathname==="/shipping")content=<SimplePage title="Shipping & Delivery" text="Shipping, delivery windows and project logistics depend on the product, order and destination. Contact BuyHoreca for current commercial delivery information."/>;else if(pathname==="/account")content=<SimplePage title="Customer Account" text="Customer account functionality can be connected to Shopify Customer Accounts. Use Shopify checkout for order processing and contact the BuyHoreca team for account-specific support."/>;else if(pathname==="/track-order")content=<TrackOrderPage/>;else if(pathname==="/blog")content=<BlogIndex/>;else if(pathname.startsWith("/blog/")){const bits=pathname.split("/").filter(Boolean);content=bits.length>=3?<BlogArticleLoader blogHandle={bits[1]} articleHandle={bits[2]}/>:<BlogIndex/>;}else content=<SimplePage title="BuyHoreca" text="Professional HoReCa equipment and supplies for hospitality businesses in the UAE."/>;
 return <div className="min-h-screen bg-white text-[#0f2630]"><a href="#main-content" className="bh-skip-link">Skip to content</a><StoreHeader cartCount={cart?.totalQuantity||0} wishlistCount={wishlist.length} setCartOpen={setCartOpen} collections={collections} cartPulse={cartPulse}/><div id="main-content">{content}</div><Footer/>{quick&&<QuickView p={quick} close={()=>setQuick(null)} onAdd={add}/>} {cartOpen&&<CartDrawer cart={cart} close={()=>setCartOpen(false)} update={update} remove={remove}/>}<div className={`bh-toast ${toast?"bh-toast-show":""}`} role="status" aria-live="polite"><CheckCircle2 size={18}/><span>{toast}</span></div><a href="https://wa.me/971565334464" target="_blank" rel="noreferrer" className="bh-whatsapp fixed bottom-5 right-5 z-40 grid size-14 place-items-center rounded-full bg-[#25D366] text-white shadow-xl" aria-label="Chat with BuyHoreca on WhatsApp"><MessageCircle size={24}/></a><nav className="bh-mobile-bar lg:hidden" aria-label="Quick navigation"><Link href="/" aria-label="Home"><HomeIcon size={18}/><span>Home</span></Link><Link href="/search" aria-label="Search"><Search size={18}/><span>Search</span></Link><Link href="/wishlist" aria-label="Wishlist"><Heart size={18}/><span>Saved</span></Link><button type="button" onClick={()=>setCartOpen(true)} className={cartPulse?"bh-cart-pulse":""} aria-label="Cart"><ShoppingCart size={18}/><span>Cart{cart?.totalQuantity?` (${cart.totalQuantity})`:""}</span></button></nav></div>;
}
function SearchPage({q,onAdd,onQuick,categories}:{q:string;onAdd:any;onQuick:any;categories:Collection[]}){const [items,setItems]=useState<Product[]>([]);const [filters,setFilters]=useState<Facet[]>([]);const [selected,setSelected]=useState<Record<string,AppliedFacet>>({});const [cursor,setCursor]=useState<string|null>(null);const [more,setMore]=useState(false);const [total,setTotal]=useState(0);const [loading,setLoading]=useState(false);const [mobileFilters,setMobileFilters]=useState(false);const [sort,setSort]=useState("RELEVANCE");const searchSortKey=sort==="TITLE"?"TITLE":sort.startsWith("PRICE")?"PRICE":"RELEVANCE";const searchReverse=sort==="PRICE_HIGH";const apply=(filter:Facet,value:FacetValue)=>{setSelected(prev=>{const next={...prev};const token=JSON.stringify(value.input);if(prev[filter.id]?.token===token)delete next[filter.id];else next[filter.id]={filterId:filter.id,label:value.label,input:value.input,token};return next})};useEffect(()=>{let live=true;if(!q){setItems([]);setFilters([]);setTotal(0);setLoading(false);setCursor(null);return}const run=async()=>{setLoading(true);setCursor(null);setMore(false);try{const r=await getSearch(q,null,Object.values(selected).map(x=>x.input),searchSortKey,searchReverse);if(live){setItems(r.products);setFilters(r.filters);setTotal(r.total);setCursor(r.pageInfo.endCursor);setMore(r.pageInfo.hasNextPage)}}catch{if(live){setItems([]);setFilters([]);setTotal(0)}}finally{if(live)setLoading(false)}};void run();return()=>{live=false}},[q,JSON.stringify(selected),searchSortKey,searchReverse]);const loadMore=async()=>{if(!cursor||!more)return;setLoading(true);try{const r=await getSearch(q,cursor,Object.values(selected).map(x=>x.input),searchSortKey,searchReverse);setItems(x=>[...x,...r.products]);setCursor(r.pageInfo.endCursor);setMore(r.pageInfo.hasNextPage)}finally{setLoading(false)}};const matches=categories.filter(c=>c.title.toLowerCase().includes(q.toLowerCase())).slice(0,12);return <main className="mx-auto max-w-[1600px] px-4 py-7"><div className="flex flex-col gap-3 border-b border-slate-200 pb-5 md:flex-row md:items-end md:justify-between"><div><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">Search</div><h1 className="mt-1 text-3xl font-bold">{q?`Results for “${q}”`:"Search the BuyHoreca catalogue"}</h1><p className="mt-2 text-sm text-slate-600">Search products, brands, categories and SKUs through Shopify.</p></div>{q&&<button type="button" onClick={()=>setMobileFilters(true)} className="inline-flex h-10 items-center justify-center gap-2 border border-slate-300 px-4 text-sm font-bold lg:hidden"><SlidersHorizontal size={15}/> Filters</button>}</div>{!q?<div className="mt-8 grid gap-4 md:grid-cols-3"><div className="border border-slate-200 bg-[#f4f7f5] p-6"><Search className="text-[#008f68]"/><h2 className="mt-3 text-lg font-bold">Search products</h2><p className="mt-2 text-sm leading-6 text-slate-600">Use the search bar above for product names, brands, categories and searchable identifiers.</p></div><div className="border border-slate-200 bg-white p-6"><Tag className="text-[#008f68]"/><h2 className="mt-3 text-lg font-bold">Browse categories</h2><Link href="/categories" className="mt-3 inline-flex text-sm font-semibold text-[#008f68]">View categories <ArrowRight size={14} className="ml-1"/></Link></div><div className="border border-slate-200 bg-white p-6"><Sparkles className="text-[#008f68]"/><h2 className="mt-3 text-lg font-bold">Shop by brand</h2><Link href="/brands" className="mt-3 inline-flex text-sm font-semibold text-[#008f68]">View brands <ArrowRight size={14} className="ml-1"/></Link></div></div>:<><div className="mt-5 grid gap-6 lg:grid-cols-[245px_1fr]"><aside className="hidden h-max border border-slate-200 bg-white p-4 lg:sticky lg:top-[150px] lg:block"><FacetFilters filters={filters} selected={selected} onSelect={apply} onClear={()=>setSelected({})}/><div className="mt-6 border-t border-slate-200 pt-4"><h3 className="text-sm font-bold">Matching categories</h3><div className="mt-2 grid gap-1">{matches.length?matches.map(c=><Link key={c.id} href={"/categories/"+c.handle} className="rounded px-2 py-2 text-xs font-semibold hover:bg-slate-50 hover:text-[#008f68]">{c.title}</Link>):<span className="px-2 py-2 text-xs text-slate-500">No matching category</span>}</div></div></aside><div><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap items-center gap-2">{Object.values(selected).map(x=><button type="button" key={x.filterId} onClick={()=>apply({id:x.filterId,label:"",values:[]},{id:x.token,label:x.label,input:x.input})} className="inline-flex items-center gap-1 rounded-full bg-[#e9f6f2] px-2.5 py-1 text-[10px] font-semibold text-[#006f52]">{x.label}<X size={11}/></button>)}<span className="text-xs font-semibold text-slate-500">{total.toLocaleString()} results</span></div><select value={sort} onChange={e=>setSort(e.target.value)} className="bh-control"><option value="RELEVANCE">Most relevant</option><option value="TITLE">A–Z</option><option value="PRICE_LOW">Price: low to high</option><option value="PRICE_HIGH">Price: high to low</option></select></div>{loading&&<div className="mb-3 flex items-center gap-2 text-xs text-slate-500"><RefreshCw size={14} className="animate-spin"/> Updating search…</div>}<div className="bh-catalog-grid">{items.map(p=><ProductCard key={p.id} p={p} onAdd={onAdd} onQuick={onQuick}/>)}</div>{!loading&&!items.length&&<div className="mt-4 rounded border border-dashed border-slate-300 bg-slate-50 p-12 text-center"><Search className="mx-auto text-slate-400"/><h2 className="mt-3 text-lg font-bold">No products found</h2><p className="mt-1 text-sm text-slate-500">Try a shorter keyword, broader category or clear one of the filters.</p></div>}{more&&<div className="mt-6 text-center"><button type="button" onClick={()=>void loadMore()} className="border border-slate-300 bg-white px-7 py-3 text-sm font-semibold hover:border-[#008f68]">Load more results</button></div>}</div></div>{mobileFilters&&<div className="fixed inset-0 z-[90] bg-black/30 lg:hidden" onMouseDown={()=>setMobileFilters(false)}><aside className="absolute left-0 top-0 h-full w-[88%] max-w-[360px] overflow-auto bg-white p-5 shadow-xl" onMouseDown={e=>e.stopPropagation()}><div className="mb-5 flex items-center justify-between"><h2 className="text-xl font-bold">Search filters</h2><button type="button" onClick={()=>setMobileFilters(false)} aria-label="Close filters"><X size={20}/></button></div><FacetFilters filters={filters} selected={selected} onSelect={apply} onClear={()=>setSelected({})}/><button type="button" onClick={()=>setMobileFilters(false)} className="mt-6 w-full bg-[#008f68] py-3 text-sm font-semibold text-white">Done</button></aside></div>}</> }</main>}

function CategoryIndex({collections}:{collections:Collection[]}){return <main className="mx-auto max-w-[1600px] px-4 py-8"><div className="text-xs font-semibold uppercase tracking-widest text-[#008f68]">Browse</div><h1 className="mt-2 text-4xl font-bold">Categories</h1><p className="mt-3 text-slate-600">Explore the live BuyHoreca collections.</p><div className="mt-7 grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6">{collections.map(c=><Link key={c.id} href={"/categories/"+c.handle} className="border border-slate-200 bg-white p-3 hover:border-[#008f68]"><div className="aspect-square bg-slate-50">{c.image?<img src={c.image.url} alt={c.title} className="h-full w-full object-contain p-4"/>:<div className="grid h-full place-items-center p-4 text-center text-sm font-bold text-slate-400">{c.title}</div>}</div><div className="mt-3 font-semibold">{c.title}</div></Link>)}</div></main>}
function CategoryLoader({handle,fallback,onAdd,onQuick}:{handle:string;fallback:Collection|null;onAdd:any;onQuick:any}){const [c,setC]=useState<Collection|null>(fallback);const [loaded,setLoaded]=useState(!!fallback);useEffect(()=>{let live=true;setLoaded(!!fallback);getCollection(handle).then(next=>{if(live){setC(next);setLoaded(true)}}).catch(()=>{if(live){setC(fallback);setLoaded(true)}});return()=>{live=false}},[handle,fallback]);if(!loaded)return <main className="mx-auto max-w-[1600px] px-4 py-14 text-center text-sm text-slate-500">Loading category…</main>;if(!c)return <SimplePage title="Category not found" text="This collection is not available in the live Shopify catalogue."><Link href="/categories" className="bh-primary-button mt-6 inline-flex">Browse categories <ArrowRight size={15}/></Link></SimplePage>;return <CategoryPage collection={c} onAdd={onAdd} onQuick={onQuick}/> }
function BrandIndex({products}:{products:Product[]}){
 const preferred=["Vollrath","iSi","Eros","Eco-Botanics","Ziora"];
 const discovered=Array.from(new Set(products.map(p=>p.brand).filter(Boolean)));
 const brands=Array.from(new Set([...preferred,...discovered])).sort((a,b)=>a.localeCompare(b));
 return <main className="mx-auto max-w-[1600px] px-4 py-8">
  <div className="text-xs font-semibold uppercase tracking-widest text-[#008f68]">Manufacturers</div>
  <h1 className="mt-2 text-4xl font-bold">Shop by Brand</h1>
  <p className="mt-3 max-w-3xl text-sm leading-6 text-slate-600">Browse manufacturers represented in the live BuyHoreca catalogue. Brand availability follows Shopify product vendor data.</p>
  <div className="mt-7 grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
   {brands.map(b=>{const src=brandLogoFor(b);return <Link key={b} href={`/brands/${encodeURIComponent(b)}`} className="bh-brand-tile group flex min-h-[118px] items-center justify-center border border-slate-200 bg-white p-5 text-center transition hover:-translate-y-0.5 hover:border-[#008f68] hover:shadow-sm">{src?<img src={src} alt={`${b} logo`} className="max-h-16 max-w-full object-contain transition duration-300 group-hover:scale-[1.03]" loading="lazy"/>:<span className="text-sm font-medium uppercase tracking-[.04em] text-slate-600 transition group-hover:text-[#008f68]">{b}</span>}</Link>})}
  </div>
 </main>
}
function BrandPage({name,onAdd,onQuick}:{name:string;onAdd:any;onQuick:any}){
 const [items,setItems]=useState<Product[]>([]);
 const logo=brandLogoFor(name);
 useEffect(()=>{getProducts(48,null,`vendor:"${name.replaceAll('"','')}"`,"BEST_SELLING",false).then(r=>setItems(r.products)).catch(()=>setItems([]))},[name]);
 return <main className="mx-auto max-w-[1600px] px-4 py-8">
  <div className="border-b border-slate-200 pb-6">
   <div className="text-xs font-semibold uppercase tracking-widest text-[#008f68]">Brand</div>
   <div className="mt-3 flex flex-wrap items-center gap-5">
    {logo&&<div className="flex h-20 w-40 items-center justify-center border border-slate-200 bg-white p-3"><img src={logo} alt={`${name} logo`} className="max-h-14 max-w-full object-contain"/></div>}
    <div><h1 className="text-4xl font-bold">{name}</h1><p className="mt-2 text-sm text-slate-600">Products available from this manufacturer in the live BuyHoreca catalogue.</p></div>
   </div>
  </div>
  {!items.length?<div className="mt-8 rounded border border-dashed border-slate-300 bg-slate-50 p-12 text-center text-sm text-slate-500">No products are currently available for this brand in the live catalogue.</div>:<div className="bh-catalog-grid mt-7">{items.map(p=><ProductCard key={p.id} p={p} onAdd={onAdd} onQuick={onQuick}/>)}</div>}
 </main>
}
function BusinessIndex(){const b=["Hotel","Bakery","Coffee Shop","Bar Supplies","Pizzeria","Ice Cream Shop","Restaurant","Catering","Banquet","Kitchen Operations","Retail Store","Food Truck"];return <main className="mx-auto max-w-[1600px] px-4 py-8"><div className="text-xs font-semibold uppercase tracking-widest text-[#008f68]">Shop by Business Type</div><h1 className="mt-2 text-4xl font-bold">Solutions for your operation</h1><div className="mt-7 grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-4">{b.map(x=><Link key={x} href={`/business/${slugify(x)}`} className="border border-slate-200 bg-white p-7 hover:border-[#008f68]"><Building2 className="text-[#008f68]"/><h2 className="mt-4 text-xl font-bold">{x}</h2><p className="mt-2 text-sm text-slate-500">Browse products commonly used by {x.toLowerCase()} operations.</p></Link>)}</div></main>}
function BusinessPage({name,products,onAdd,onQuick}:{name:string;products:Product[];onAdd:any;onQuick:any}){const terms=name.toLowerCase().split(" ");const list=products.filter(p=>terms.some(t=>`${p.name} ${p.productType||""} ${p.description}`.toLowerCase().includes(t))).slice(0,24);return <main className="mx-auto max-w-[1600px] px-4 py-8"><div className="text-xs font-semibold uppercase tracking-widest text-[#008f68]">Business Type</div><h1 className="mt-2 text-4xl font-bold">{name}</h1><p className="mt-3 text-slate-600">Products selected from the live BuyHoreca catalogue for this type of operation.</p><div className="mt-7 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5">{list.map(p=><ProductCard key={p.id} p={p} onAdd={onAdd} onQuick={onQuick}/>)}</div></main>}
function CartPage({cart,onUpdate,onRemove}:{cart:Cart|null;onUpdate:any;onRemove:any}){return <main className="mx-auto max-w-[1300px] px-4 py-10"><h1 className="text-4xl font-bold">Shopping Cart</h1>{!cart?.lines.length?<div className="mt-7 border border-slate-200 bg-white p-10 text-center"><p className="text-lg font-bold">Your cart is empty.</p><Link href="/shop" className="mt-5 inline-block rounded bg-[#008f68] px-6 py-3 text-sm font-bold text-white">Continue Shopping</Link></div>:<div className="mt-7 grid gap-7 lg:grid-cols-[1fr_360px]"><div className="border border-slate-200 bg-white">{cart.lines.map(l=><div key={l.id} className="flex gap-4 border-b border-slate-200 p-5"><div className="size-24 shrink-0 bg-slate-50 p-2"><img src={l.merchandise.image?.url||"/product-placeholder.svg"} alt="" className="h-full w-full object-contain"/></div><div className="flex-1"><Link href={`/products/${l.merchandise.product.handle}`} className="font-semibold">{l.merchandise.product.title}</Link><div className="mt-1 text-xs text-slate-500">{l.merchandise.title}</div><div className="mt-2 font-bold">{money(l.merchandise.price)}</div><div className="mt-3 flex items-center gap-2"><button onClick={()=>onUpdate(l.id,l.quantity-1)} className="grid size-8 place-items-center border"><Minus size={13}/></button><span className="w-7 text-center text-sm font-bold">{l.quantity}</span><button onClick={()=>onUpdate(l.id,l.quantity+1)} className="grid size-8 place-items-center border"><Plus size={13}/></button><button onClick={()=>onRemove(l.id)} className="ml-3 text-xs font-bold text-red-600">Remove</button></div></div></div>)}</div><div className="h-max border border-slate-200 bg-white p-6"><h2 className="text-xl font-bold">Order Summary</h2><div className="mt-6 flex justify-between text-sm"><span>Subtotal</span><b>{money(cart.cost.subtotalAmount)}</b></div><div className="mt-3 flex justify-between text-xl font-bold"><span>Total</span><span>{money(cart.cost.totalAmount)}</span></div><a href={cart.checkoutUrl} className="mt-6 flex h-12 items-center justify-center rounded bg-[#008f68] text-sm font-semibold text-white">Proceed to Checkout</a></div></div>}</main>}
function Wishlist({ids,products,onAdd,onQuick}:{ids:string[];products:Product[];onAdd:any;onQuick:any}){const [snapshots,setSnapshots]=useState<Product[]>([]);useEffect(()=>{setSnapshots(Object.values(readStoredSnapshots(WISHLIST_SNAPSHOT_KEY)))},[ids]);const map=new Map([...snapshots,...products].map(p=>[p.id,p]));const list=ids.map(id=>map.get(id)).filter(Boolean) as Product[];const clearAll=()=>{writeStoredJSON(WISHLIST_KEY,[]);writeStoredJSON(WISHLIST_SNAPSHOT_KEY,{});window.dispatchEvent(new CustomEvent("buyhoreca:wishlist",{detail:[]}));window.dispatchEvent(new CustomEvent("buyhoreca:toast",{detail:"Wishlist cleared"}))};return <main className="mx-auto max-w-[1600px] px-4 py-8"><div className="flex flex-col gap-4 border-b border-slate-200 pb-5 md:flex-row md:items-end md:justify-between"><div><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">Saved products</div><h1 className="mt-1 text-4xl font-bold">Wishlist <span className="text-lg font-bold text-slate-400">({ids.length})</span></h1><p className="mt-2 text-sm text-slate-500">Keep products here for later purchasing or quote requests.</p></div><div className="flex items-center gap-3"><Link href="/shop" className="text-sm font-bold text-[#008f68]">Continue shopping <ArrowRight size={14} className="inline"/></Link>{ids.length>0&&<button type="button" onClick={clearAll} className="text-sm font-bold text-slate-500 hover:text-red-600">Clear wishlist</button>}</div></div>{!list.length?<div className="mt-8 rounded border border-dashed border-slate-300 bg-slate-50 p-12 text-center"><Heart className="mx-auto text-slate-400"/><h2 className="mt-3 text-xl font-bold">Your wishlist is empty</h2><p className="mt-1 text-sm text-slate-500">Save products with the heart button and they will stay here on this browser.</p><Link href="/shop" className="mt-5 inline-flex items-center gap-2 rounded bg-[#008f68] px-5 py-3 text-sm font-semibold text-white">Browse products <ArrowRight size={14}/></Link></div>:<div className="bh-catalog-grid mt-6">{list.map(p=><ProductCard key={p.id} p={p} onAdd={onAdd} onQuick={onQuick}/>)}</div>}</main>}
function ComparePage({ids,products,onAdd,onQuick}:{ids:string[];products:Product[];onAdd:any;onQuick:any}){const [snapshots,setSnapshots]=useState<Product[]>([]);useEffect(()=>{try{const data=JSON.parse(localStorage.getItem("buyhoreca_compare_snapshots")||"{}");if(data&&typeof data==="object")setSnapshots(Object.values(data))}catch{}},[ids]);const map=new Map([...snapshots,...products].map(p=>[p.id,p]));const list=ids.map(id=>map.get(id)).filter(Boolean) as Product[];const remove=(id:string)=>{try{const next=ids.filter(x=>x!==id);const data=JSON.parse(localStorage.getItem("buyhoreca_compare_snapshots")||"{}");if(data&&typeof data==="object")delete data[id];localStorage.setItem("buyhoreca_compare_snapshots",JSON.stringify(data));localStorage.setItem("buyhoreca_compare",JSON.stringify(next));window.dispatchEvent(new CustomEvent("buyhoreca:compare",{detail:next}))}catch{}};return <main className="mx-auto max-w-[1600px] px-4 py-8"><div className="flex flex-col gap-2 border-b border-slate-200 pb-5 md:flex-row md:items-end md:justify-between"><div><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">Compare</div><h1 className="mt-1 text-4xl font-bold">Compare products</h1><p className="mt-2 text-sm text-slate-600">Compare up to four products from the live BuyHoreca catalogue.</p></div><Link href="/shop" className="text-sm font-bold text-[#008f68]">Continue shopping <ArrowRight size={14} className="inline"/></Link></div>{!list.length?<div className="mt-8 rounded border border-dashed border-slate-300 bg-slate-50 p-12 text-center"><Boxes className="mx-auto text-slate-400"/><h2 className="mt-3 text-xl font-bold">Nothing to compare yet</h2><p className="mt-1 text-sm text-slate-500">Use the compare icon on product cards to add products here.</p></div>:<><div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{list.map(p=><div key={p.id} className="rounded border border-slate-200 bg-white p-4"><div className="flex justify-end"><button type="button" onClick={()=>remove(p.id)} className="text-xs font-bold text-slate-400 hover:text-red-600">Remove</button></div><div className="mt-2 aspect-square bg-slate-50 p-4"><img src={p.images[0]?.url||"/product-placeholder.svg"} alt={p.name} className="h-full w-full object-contain"/></div><div className="mt-4 text-[10px] font-bold uppercase tracking-wider text-slate-500">{p.brand}</div><Link href={p.href} className="mt-1 block text-sm font-bold hover:text-[#008f68]">{p.name}</Link><div className="mt-2"> <Stars value={p.rating} count={p.reviewCount}/></div><div className="mt-2 text-lg font-bold">{money(p.price)}</div><div className="mt-1 text-xs text-slate-500">SKU: {p.variants[0]?.sku||"—"}</div><button type="button" onClick={()=>onAdd(p)} className="mt-4 flex h-10 w-full items-center justify-center gap-2 rounded bg-[#008f68] text-xs font-semibold text-white"><ShoppingCart size={14}/> Add to Cart</button></div>)}</div><div className="mt-6 overflow-x-auto rounded border border-slate-200 bg-white"><table className="min-w-[760px] w-full text-sm"><tbody><tr className="border-b border-slate-200"><th className="w-48 bg-slate-50 p-4 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Attribute</th>{list.map(p=><td key={p.id} className="p-4 font-bold">{p.name}</td>)}</tr>{([
  ["Brand",(p:Product)=>p.brand],
  ["Product Type",(p:Product)=>p.productType||"—"],
  ["SKU",(p:Product)=>p.variants[0]?.sku||"—"],
  ["Availability",(p:Product)=>p.availableForSale?"Available":"Quote"],
  ["Price",(p:Product)=>money(p.price)]
] as Array<[string,(p:Product)=>string]>).map(([label,get])=><tr key={String(label)} className="border-b border-slate-100 last:border-0"><th className="bg-slate-50 p-4 text-left text-xs font-bold text-slate-500">{label}</th>{list.map(p=><td key={p.id} className="p-4 text-sm font-semibold text-slate-700">{(get as any)(p)}</td>)}</tr>)}</tbody></table></div></>}</main>}

function QuickView({p,close,onAdd}:{p:Product;close:()=>void;onAdd:any}){return <div className="fixed inset-0 z-[110] grid place-items-center bg-black/40 p-4" onMouseDown={close}><div onMouseDown={e=>e.stopPropagation()} className="max-h-[92vh] w-full max-w-4xl overflow-auto bg-white p-6 shadow-2xl"><div className="flex justify-end"><button type="button" onClick={close} className="grid size-10 place-items-center border"><X/></button></div><div className="grid gap-7 md:grid-cols-2"><div className="aspect-square bg-slate-50 p-6"><img src={p.images[0]?.url||"/product-placeholder.svg"} alt={p.name} className="h-full w-full object-contain"/></div><div><div className="text-xs font-bold uppercase tracking-widest text-[#008f68]">{p.brand}</div><h2 className="mt-2 text-3xl font-bold">{p.name}</h2><Stars value={p.rating} count={p.reviewCount}/><div className="mt-5 text-2xl font-bold">{money(p.price)}</div><p className="mt-4 line-clamp-6 text-sm leading-6 text-slate-600">{p.description}</p><button type="button" onClick={()=>onAdd(p)} className="mt-6 h-12 rounded bg-[#008f68] px-7 text-sm font-semibold text-white">Add to Cart</button><Link href={p.href} onClick={close} className="ml-3 inline-flex h-12 items-center border border-slate-300 px-5 text-sm font-bold">Full Product</Link></div></div></div></div>}

export default App;
